[
  {
    "text": "Positive- and negative-branch errors can compensate in the guided prediction, making the objective under-identified at the branch level.",
    "topic": "Branch-level error compensation"
  },
  {
    "text": "Naive matching remains effective under shared negative conditioning, where both branch errors decrease jointly.",
    "topic": "Naive matching effectiveness"
  },
  {
    "text": "When the model's native CFG schema retains privileged information in the teacher's negative branch that is unavailable to the student, joint reduction of branch errors breaks down, leading to antagonistic branch-error dynamics.",
    "topic": "Negative Branch Asymmetry (NBA)"
  },
  {
    "text": "Positive--Direction Matching (PDM) is introduced as a branch-aware OPD objective that separately constrains the positive prediction and the CFG conditional direction to address NBA.",
    "topic": "Positive--Direction Matching (PDM)"
  },
  {
    "text": "PDM enables more robust and effective knowledge transfer in dense-to-sparse video control, reducing sensitivity to inference guidance scales compared to naive guided matching.",
    "topic": "PDM application in video control"
  }
]
